:["postgres=arwdDxtm/postgres"],"oid":"18984","rls":true,"name":"audio_producer_permit","force":false,"owner":"16384"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19033","rls":true,"name":"company_registry_worker_pilots","force":false,"owner":"17960"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19045","rls":true,"name":"company_registry_worker_pilot_requests","force":false,"owner":"17960"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19094","rls":true,"name":"platform_review_grants","force":false,"owner":"17960"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19110","rls":true,"name":"signup_review_methods","force":false,"owner":"17960"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19127","rls":true,"name":"signup_review_synthetic_subjects","force":false,"owner":"17960"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19137","rls":true,"name":"signup_review_evidence","force":false,"owner":"17960"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19176","rls":true,"name":"signup_identity_evidence_bindings","force":false,"owner":"17960"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19194","rls":true,"name":"signup_review_events","force":false,"owner":"17960"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19226","rls":true,"name":"review_grant_revision_bindings","force":false,"owner":"17960"},{"acl":["postgres=arwdDxtm/postgres"],"oid":"19470","rls":true,"name":"audio_attachment_scopes","force":false,"owner":"16384"},{"acl":["postgres=arwdDxtm/postgres"],"oid":"19484","rls":true,"name":"audio_attachment_fixture","force":false,"owner":"16384"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19539","rls":true,"name":"company_registry_execution_windows","force":false,"owner":"17960"},{"acl":["connect_hmac_registration=arwdDxtm/connect_hmac_registration"],"oid":"19550","rls":true,"name":"company_registry_execution_audit","force":false,"owner":"17960"}],"members":[{"oid":"17961","member":"16384","roleid":"17960","grantor":"10","set_option":false,"admin_option":true,"inherit_option":false},{"oid":"17962","member":"16384","roleid":"17960","grantor":"16384","set_option":false,"admin_option":false,"inherit_option":false}],"functions":[{"acl":["connect_hmac_registration=X/connect_hmac_registration"],"oid":"18544","args":"25 25 1184 1184 1082","name":"company_registry_source_allowed","owner":"17960","config":["search_path=\"\""],"parallel":"u","volatile":"v","srcSha256":"7e6625054f1b2a83981f1236333c882ba1227a06ba16e3d6c3150c12108ba86a","securityDefiner":false},{"acl":["connect_hmac_registration=X/connect_hmac_registration","service_role=X/connect_hmac_registration"],"oid":"18615","args":"2950 2950 3802","name":"finish_company_registry_job","owner":"17960","config":["search_path=\"\""],"parallel":"u","volatile":"v","srcSha256":"821a37aa4f982ee280394d65fadce2da5cf9613a844d984241ce767cbf9772ed","securityDefiner":true},{"acl":["connect_hmac_registration=X/connect_hmac_registration"],"oid":"19567","args":"","name":"registry_execution_policy_hash","owner":"17960","config":["search_path=\"\""],"parallel":"u","volatile":"v","srcSha256":"08252500915efc04e800cbec5260269661d8fa02556b253e68a6ff339278d9b8","securityDefiner":true},{"acl":["connect_hmac_registration=X/connect_hmac_registration"],"oid":"19585","args":"2950 2950 2950 2950 1184 1184 1082","name":"registry_execution_result_allowed","owner":"17960","config":["search_path=\"\""],"parallel":"u","volatile":"v","srcSha256":"99d002429dbb48c00ef9a908f56ea7c7b596d3a7c2b0858305893d6bbbc90b85","securityDefiner":true}],"constraints":[{"name":"company_registry_sources_max_age_seconds_check","validated":true,"definition":"CHECK (((max_age_seconds >= 1) AND (max_age_seconds <= 86400)))"},{"name":"company_registry_sources_pkey","validated":true,"definition":"PRIMARY KEY (source, policy_version)"},{"name":"registry_legal_policy_exact","validated":true,"definition":"CHECK (((policy_version = ''company-name-v1''::text) OR ((policy_version = ''company-legal-name-v2''::text) AND (source = ''minhareceita-cnpj-v1''::text) AND (NOT synthetic_only))))"},{"name":"registry_source_exact_mode","validated":true,"definition":"CHECK ((((source = ''synthetic-cnpj-v1''::text) AND synthetic_only AND (max_dataset_age_days IS NULL)) OR ((source = ''minhareceita-cnpj-v1''::text) AND (NOT synthetic_only) AND (max_dataset_age_days IS NOT NULL) AND ((max_dataset_age_days >= 1) AND (max_dataset_age_days <= 45)))))"}]}'::jsonb then raise exception 'Monthly policy catalog differs';end if;if exists(select 1 from private.company_registry_sources where enabled)or exists(select 1 from private.company_registry_execution_windows where closed_at is null)then raise exception 'Monthly policy requires closed CNPJ';end if;end$$;
grant connect_hmac_registration to postgres with inherit false,set true;set local role connect_hmac_registration;
alter table private.company_registry_sources drop constraint registry_source_exact_mode,add constraint registry_source_exact_mode CHECK ((((source = 'synthetic-cnpj-v1'::text) AND synthetic_only AND (max_dataset_age_days IS NULL)) OR ((source = 'minhareceita-cnpj-v1'::text) AND (NOT synthetic_only) AND (max_dataset_age_days IS NOT NULL) AND ((max_dataset_age_days >= 1) AND ((max_dataset_age_days <= 45) OR ((policy_version = 'company-legal-name-v2'::text) AND (max_dataset_age_days = 62)))))));
CREATE OR REPLACE FUNCTION private.company_registry_source_allowed(p_source text, p_policy text, p_observed timestamp with time zone, p_expires timestamp with time zone, p_dataset date)
 RETURNS boolean
 LANGUAGE sql
 SET search_path TO ''
AS $function$
 select coalesce(p_policy='company-legal-name-v2'and p_source='minhareceita-cnpj-v1'and isfinite(p_observed)and isfinite(p_expires)and p_observed<=clock_timestamp()and p_expires>clock_timestamp()and exists(
 select 1 from private.company_registry_sources s where s.source=p_source and s.policy_version=p_policy and s.enabled
 and p_expires<=p_observed+make_interval(secs=>s.max_age_seconds)
 and((s.source='synthetic-cnpj-v1'and s.synthetic_only and p_dataset is null)
 or(s.source='minhareceita-cnpj-v1'and not s.synthetic_only and isfinite(p_dataset)
 and s.max_dataset_age_days=62 and extract(day from p_dataset)=1 and p_dataset<=((clock_timestamp()at time zone'UTC')::date)
 and clock_timestamp()<least(((p_dataset+s.max_dataset_age_days)::timestamp at time zone'UTC'),((p_dataset+interval'2months')at time zone'UTC'))
 and p_expires<=least(((p_dataset+s.max_dataset_age_days)::timestamp at time zone'UTC'),((p_dataset+interval'2months')at time zone'UTC'))))),false)
$function$;
CREATE OR REPLACE FUNCTION private.finish_company_registry_job(p_job uuid, p_lease uuid, p_result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j private.company_registry_jobs;r private.company_registrations;cfg private.company_registry_sources;v_state text;result_digest bytea;observed timestamptz;expiry timestamptz;dataset date;ref uuid;new_proof uuid;value text;
begin
 perform pg_advisory_xact_lock_shared(78104,0);
 if p_job is null or p_lease is null or jsonb_typeof(p_result)is distinct from'object'then perform private.hmac_model_fail('P0001');end if;
 v_state:=p_result->>'state';
 if v_state in('mismatch','not-found','unavailable')then
  if not private.company_registry_json_keys(p_result,array['state'])then perform private.hmac_model_fail('P0001');end if;
 elsif v_state='ready'then
  if not private.company_registry_json_keys(p_result,array['state','source_reference','matched_by','legal_name','official_name','normalised_name','registration_status','observed_at','dataset_date'])
   or jsonb_typeof(p_result->'registration_status')is distinct from'number'or p_result->>'registration_status'not in('1','2','3','4','8')
   or p_result->>'matched_by'is distinct from'legal-name' or p_result->>'official_name'is distinct from p_result->>'legal_name'
   or jsonb_typeof(p_result->'source_reference')is distinct from'string'or(p_result->>'source_reference')!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
   or jsonb_typeof(p_result->'observed_at')is distinct from'string'or(p_result->>'observed_at')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?Z$'
   then perform private.hmac_model_fail('P0001');end if;
  foreach value in array array['legal_name','official_name','normalised_name']loop
   if jsonb_typeof(p_result->value)is distinct from'string'or char_length(p_result->>value)<1 or char_length(p_result->>value)>(case when value='normalised_name'then 400 else 200 end)then perform private.hmac_model_fail('P0001');end if;
  end loop;
  if p_result->'dataset_date'<>'null'::jsonb then
   if jsonb_typeof(p_result->'dataset_date')is distinct from'string'or(p_result->>'dataset_date')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'then perform private.hmac_model_fail('P0001');end if;
   dataset:=(p_result->>'dataset_date')::date;if to_char(dataset,'YYYY-MM-DD')<>p_result->>'dataset_date'then perform private.hmac_model_fail('P0001');end if;
  end if;
  ref:=(p_result->>'source_reference')::uuid;observed:=(p_result->>'observed_at')::timestamptz;
 else perform private.hmac_model_fail('P0001');end if;
 result_digest:=sha256(convert_to(p_result::text,'UTF8'));
 select*into strict j from private.company_registry_jobs z where z.job_id=p_job;
 perform pg_advisory_xact_lock(78103,hashtext(j.subject::text));
 select*into r from private.company_registrations z where z.requester_id=j.subject and z.request_id=j.request_id for update;
 select*into strict j from private.company_registry_jobs z where z.job_id=p_job for update;
 if j.policy_version<>'company-legal-name-v2'or j.source<>'minhareceita-cnpj-v1'or j.lease_id is distinct from p_lease then perform private.hmac_model_fail('P0001');end if;
 if not private.fence_registry_execution_window(p_lease,j.subject,j.requester_session,j.request_id)then perform private.hmac_model_fail('P0001');end if;
 if j.result_hash is not null then
  if j.result_hash is distinct from result_digest then perform private.hmac_model_fail('P0001');end if;
  if not private.company_registry_job_session(j.subject,j.requester_session,j.requester_expires)or private.company_registry_snapshot(j.subject,j.request_id)is distinct from j.request_snapshot or not exists(select 1 from private.company_registry_sources z where(z.source,z.policy_version)=(j.source,j.policy_version)and not z.enabled)then return jsonb_build_object('job_id',j.job_id,'state','unavailable');end if;
  return jsonb_build_object('job_id',j.job_id,'state',j.state);
 end if;
 if j.state<>'checking'or j.lease_expires_at<=clock_timestamp()then perform private.hmac_model_fail('P0001');end if;
 select*into cfg from private.company_registry_sources z where(z.source,z.policy_version)=(j.source,j.policy_version)for share;
 if r.state is distinct from'pending'or cfg.enabled or not private.company_registry_job_session(j.subject,j.requester_session,j.requester_expires)
 or private.company_registry_snapshot(j.subject,j.request_id)is distinct from j.request_snapshot
 then update private.company_registry_jobs set state='retired',result_hash=result_digest,updated_at=clock_timestamp()where job_id=j.job_id;return jsonb_build_object('job_id',j.job_id,'state','unavailable');end if;
 if v_state='ready'then
  if private.company_registry_legal_name_key(p_result->>'legal_name')is null
   or private.company_registry_legal_name_key(p_result->>'legal_name')is distinct from private.company_registry_legal_name_key((select name from public.companies where id=j.company_id))
   or p_result->>'normalised_name'is distinct from private.company_registry_legal_name_key(p_result->>'legal_name')then perform private.hmac_model_fail('P0001');end if;
  expiry:=least(observed+make_interval(secs=>cfg.max_age_seconds),(select expires_at from private.company_registry_execution_windows where operation_id=p_lease));
  if cfg.source='minhareceita-cnpj-v1'then
   if dataset is null or extract(day from dataset)<>1 then perform private.hmac_model_fail('P0001');end if;
   expiry:=least(expiry,((dataset+cfg.max_dataset_age_days)::timestamp at time zone'UTC'),((dataset+interval'2months')at time zone'UTC'));
  elsif dataset is not null then perform private.hmac_model_fail('P0001');end if;
  if not private.registry_execution_result_allowed(p_lease,j.subject,j.requester_session,j.request_id,observed,expiry,dataset)then v_state:='unavailable';
  else
   if not exists(select 1 from private.company_controls c where c.company_id=j.company_id and c.state='pending'and c.cnpj is null and c.representation_state='unconfirmed')
   or private.company_registry_snapshot(j.subject,j.request_id)is distinct from j.request_snapshot then perform private.hmac_model_fail('P0001');end if;
   new_proof:=gen_random_uuid();
   insert into private.company_registry_proofs(proof_id,subject,request_id,company_id,cnpj,requested_name,request_snapshot,source,policy_version,source_reference,matched_by,legal_name,official_name,normalised_name,registration_status,observed_at,expires_at,dataset_date)
    values(new_proof,j.subject,j.request_id,j.company_id,r.cnpj,(select c.name from public.companies c where c.id=j.company_id),j.request_snapshot,j.source,j.policy_version,ref,p_result->>'matched_by',p_result->>'legal_name',p_result->>'official_name',p_result->>'normalised_name',p_result->>'registration_status',observed,expiry,dataset);
  end if;
 end if;
 update private.company_registry_jobs set state=v_state,proof_id=new_proof,result_hash=result_digest,retry_after=case when v_state='ready'then null else clock_timestamp()+interval'30seconds'end,updated_at=clock_timestamp()where job_id=j.job_id;
 if not private.company_registry_job_session(j.subject,j.requester_session,j.requester_expires)
 or private.company_registry_snapshot(j.subject,j.request_id)is distinct from j.request_snapshot
 or not exists(select 1 from private.company_registry_sources z where(z.source,z.policy_version)=(j.source,j.policy_version)and not z.enabled)
 then perform private.hmac_model_fail('P0001');end if;
 return jsonb_build_object('job_id',j.job_id,'state',v_state);
exception when others or query_canceled or assert_failure then perform private.hmac_model_fail(sqlstate);return null;end$function$;
CREATE OR REPLACE FUNCTION private.registry_execution_policy_hash()
 RETURNS bytea
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select sha256(convert_to(jsonb_build_object('freshness_policy','calendar-month-v1','source',s.source,'policy',s.policy_version,'max_age',s.max_age_seconds,'dataset_days',s.max_dataset_age_days,'synthetic',s.synthetic_only)::text,'UTF8'))
 from private.company_registry_sources s where s.source='minhareceita-cnpj-v1'and s.policy_version='company-legal-name-v2'
 and not s.enabled and not s.synthetic_only and s.max_age_seconds=600 and s.max_dataset_age_days=62
$function$;
CREATE OR REPLACE FUNCTION private.registry_execution_result_allowed(p_op uuid, p_subject uuid, p_session uuid, p_request uuid, p_observed timestamp with time zone, p_expires timestamp with time zone, p_dataset date)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select coalesce(isfinite(p_observed)and isfinite(p_expires)and isfinite(p_dataset)and p_observed<=clock_timestamp()and p_expires>clock_timestamp()
 and extract(day from p_dataset)=1 and p_dataset<=((clock_timestamp()at time zone'UTC')::date)
 and exists(select 1 from private.company_registry_execution_windows w join private.company_registry_sources s on(s.source,s.policy_version)=(w.source,w.policy_version)
 join private.company_registrations r on r.requester_id=w.subject and r.request_id=w.request_id
 where w.operation_id=p_op and w.subject=p_subject and w.session_id=p_session and w.request_id=p_request
 and r.company_id=w.company_id and r.cnpj=w.cnpj and private.company_registry_snapshot(w.subject,w.request_id)=w.request_snapshot
 and private.registry_execution_temporal_live(w.operation_id,w.subject,w.session_id,w.request_id)
 and s.max_dataset_age_days=62 and p_expires<=w.expires_at and p_expires<=p_observed+make_interval(secs=>s.max_age_seconds)
 and clock_timestamp()<least(((p_dataset+s.max_dataset_age_days)::timestamp at time zone'UTC'),((p_dataset+interval'2months')at time zone'UTC'))
 and p_expires<=least(((p_dataset+s.max_dataset_age_days)::timestamp at time zone'UTC'),((p_dataset+interval'2months')at time zone'UTC'))),false)
$function$;
